## Real-Time Bidirectional Communication

### WebSocket Server

```xiom
use xiom.websocket;

fn main() -> Int {
  let mut server = websocket::Server::new();

  server.on_connect(|client| {
    io.println("Client connected: " + client.id.to_str());

    // Send welcome message
    client.send("Welcome to the server!");

    // Handle messages
    client.on_message(|msg| {
      io.println("Received: " + msg);
      // Echo back
      client.send("Echo: " + msg);
    });

    client.on_close(|| {
      io.println("Client disconnected");
    });
  });

  server.listen(8080)?;
  return 0;
}
```

### WebSocket Client

```xiom
fn main() -> Int {
  let mut client = websocket::Client::connect("ws://localhost:8080")?;

  client.on_message(|msg| {
    io.println("Server: " + msg);
  });

  client.send("Hello from client!");

  // Keep connection alive
  os.sleep(30_000);
  return 0;
}
```

### Broadcasting

```xiom
pub type ChatServer = {
  clients: Vec[WebSocketClient];
}

impl ChatServer {
  fn broadcast(self: &ChatServer, message: Str) {
    for client in &self.clients {
      client.send(message);
    }
  }

  fn broadcast_except(self: &ChatServer, sender: &WebSocketClient, message: Str) {
    for client in &self.clients {
      if client.id != sender.id {
        client.send(message);
      }
    }
  }
}
```

### JSON over WebSocket

```xiom
pub type Message = enum {
  Chat(text: Str, user: Str),
  SystemNotification(text: Str),
  UserJoined(user: Str),
}

client.on_message(|raw| {
  let msg: Message = json::from_str(&raw)?;
  match msg {
    Message::Chat(text, user) => display_chat(user, text),
    Message::SystemNotification(text) => display_notification(text),
    Message::UserJoined(user) => display_join(user),
  }
});
```

### Reconnection

```xiom
fn connect_with_retry(url: &Str, max_retries: Int) -> Result<WebSocketClient, Error> {
  for attempt in 0..max_retries {
    match websocket::Client::connect(url) {
      Ok(client) => return Ok(client),
      Err(e) => {
        io.eprintln("Connection failed (attempt " + attempt.to_str() + "): " + e.to_str());
        os.sleep(2u64.pow(attempt) * 1000);  // Exponential backoff
      },
    }
  }
  return Err("Max reconnection attempts reached");
}
```

